import{_ as a,o as d,c as e,a3 as r}from"./chunks/framework.BlfGB29P.js";const _=JSON.parse('{"title":"单体与微前端","description":"","frontmatter":{"title":"单体与微前端","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/architecture/monolith-microfrontend.md","filePath":"frontend/decisions/architecture/monolith-microfrontend.md","lastUpdated":1785589115000}'),i={name:"frontend/decisions/architecture/monolith-microfrontend.md"};function o(l,t,h,n,c,s){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="单体与微前端" tabindex="-1">单体与微前端 <a class="header-anchor" href="#单体与微前端" aria-label="Permalink to &quot;单体与微前端&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>微前端解决的是多个团队需要独立交付同一用户界面时的组织和运行时边界，不是“大项目的标准升级”。在比较前，应把模块化单体作为独立候选：它能提供清晰代码边界，同时保留一个构建、一个运行时和原子发布。</p><p>具体集成模型与隔离机制参见<a href="/frontend/guide/engineering/architecture/micro-frontends">微前端模型与运行时边界</a>。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>当一个应用变慢时，原因可能是构建配置、模块耦合、测试策略或产品协作，并不必然需要微前端。只有团队确实需要不同发布节奏、技术生命周期或故障隔离，运行时拆分才可能带来净收益。</p><p>问题应写成“哪些团队为什么无法在现有交付单元中独立工作”，而不是“项目达到多少行就上微前端”。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-必须保持的用户和安全边界" tabindex="-1">2.1 必须保持的用户和安全边界 <a class="header-anchor" href="#_2-1-必须保持的用户和安全边界" aria-label="Permalink to &quot;2.1 必须保持的用户和安全边界&quot;">​</a></h3><ul><li>登录、权限、导航和关键交易不能因子应用组合而出现不一致；</li><li>无障碍焦点、路由返回、错误恢复和性能预算仍按整个页面验收；</li><li>子应用不能绕过 CSP、依赖准入和敏感数据边界；</li><li>必须定义壳与子应用的版本兼容、降级和回滚策略。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>重点比较团队自主性、原子变更需求、共享状态、运行时隔离、首屏与重复依赖、开发调试、平台维护和迁移退出成本。仓库大小和页面数量只能提供背景，不能单独决定架构。</p><h2 id="_3-候选方案" tabindex="-1">3. 候选方案 <a class="header-anchor" href="#_3-候选方案" aria-label="Permalink to &quot;3. 候选方案&quot;">​</a></h2><h3 id="_3-1-单体应用" tabindex="-1">3.1 单体应用 <a class="header-anchor" href="#_3-1-单体应用" aria-label="Permalink to &quot;3.1 单体应用&quot;">​</a></h3><p>一个代码库、构建和制品，模块边界较轻。适合单一团队或高频跨域需求，原子修改和统一体验最简单；规模增长后可能出现构建变慢和代码所有权模糊。</p><h3 id="_3-2-模块化单体" tabindex="-1">3.2 模块化单体 <a class="header-anchor" href="#_3-2-模块化单体" aria-label="Permalink to &quot;3.2 模块化单体&quot;">​</a></h3><p>仍然统一部署，但通过特性模块、依赖规则和所有者建立边界。它保留原子变更和单运行时，通常是多团队应用应先尝试的状态。限制是团队仍需协调同一发布窗口和主干质量。</p><h3 id="_3-3-微前端" tabindex="-1">3.3 微前端 <a class="header-anchor" href="#_3-3-微前端" aria-label="Permalink to &quot;3.3 微前端&quot;">​</a></h3><p>多个团队拥有可独立构建或部署的子应用，由壳在运行时或服务端组合。它以重复基础设施、跨应用协议、性能和体验治理换取交付自主性。若团队边界不稳定，拆分会放大协作成本。</p><h3 id="_3-4-独立产品入口" tabindex="-1">3.4 独立产品入口 <a class="header-anchor" href="#_3-4-独立产品入口" aria-label="Permalink to &quot;3.4 独立产品入口&quot;">​</a></h3><p>某些模块无需在同一页面组合，可拆为独立站点，通过统一身份和导航连接。这比运行时微前端简单，适合用户任务本来就相对独立的场景。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>单体</th><th>模块化单体</th><th>微前端</th><th>独立产品入口</th></tr></thead><tbody><tr><td>原子跨域修改</td><td>最容易</td><td>容易</td><td>需协调协议版本</td><td>通常不需要</td></tr><tr><td>独立发布</td><td>不支持</td><td>不支持或有限</td><td>支持</td><td>支持</td></tr><tr><td>运行时复杂度</td><td>低</td><td>低</td><td>高</td><td>中</td></tr><tr><td>统一体验</td><td>容易</td><td>容易</td><td>需治理</td><td>允许一定差异</td></tr><tr><td>故障隔离</td><td>弱</td><td>弱至中</td><td>可增强但非自动</td><td>较强</td></tr><tr><td>平台投入</td><td>低</td><td>中</td><td>高</td><td>中</td></tr></tbody></table><p>微前端并不自动隔离 JavaScript 故障或样式。是否真正隔离取决于 iframe、进程、运行时容器和错误边界等具体机制。</p><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>案例：一个 B2B 平台有订单、库存、财务、分析四个小组，共用身份、导航和设计系统；过去季度 35% 的需求横跨两个以上领域，但发布冲突每月只有一至两次。</p><p>推荐先采用模块化单体：设置领域所有者、边界检查和按模块测试，并优化增量构建。当前跨域原子变更很多，强行独立部署会把仓库冲突变成协议和版本协调；每月少量发布冲突不足以支付微前端平台成本。</p><p>财务报表若未来形成独立产品、团队和发布窗口，可先拆为独立入口；只有必须在同一壳中组合且独立发布价值被数据证明时，再引入微前端。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>模块化单体要求所有团队共同维护主干质量和发布纪律，但避免了运行时重复、跨应用通信和多版本设计系统。团队接受发布仍需协调，并以自动化门禁和更小批次缓解。</p><p>若将来转向微前端，退出成本包括壳平台、共享依赖策略、跨应用事件协议、监控聚合、本地联调和统一发布控制。进入之前应明确谁长期维护这些能力。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>单团队应用通常不需要微前端。</li><li>只是构建慢时，应先测量模块图、缓存和测试任务，而不是改变运行架构。</li><li>高度共享状态、频繁跨域原子交易的页面不适合强行独立部署。</li><li>团队没有稳定所有权时，微前端只会让模糊边界变成网络边界。</li><li>允许用户跳转到独立产品时，不必为了“无感组合”承担运行时集成。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>四个小组是否需要微前端以减少协作冲突</td></tr><tr><td>硬约束</td><td>统一身份和审计；订单到财务需原子上线；首屏预算不增加</td></tr><tr><td>候选</td><td>单体、模块化单体、微前端、独立产品入口</td></tr><tr><td>决定</td><td>采用模块化单体，暂不引入微前端</td></tr><tr><td>证据</td><td>跨域需求 35%；发布冲突每月 1 至 2 次；构建瓶颈可由缓存解决</td></tr><tr><td>补偿措施</td><td>模块所有者、依赖规则、增量 CI、每周固定发布窗口</td></tr><tr><td>接受代价</td><td>仍共享主干和发布责任</td></tr><tr><td>退出路径</td><td>路由和领域 API 保持清楚，为未来独立入口保留边界</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>连续两个季度出现每周多次发布阻塞、团队需要不同合规或技术生命周期、领域间原子变更降到 10% 以下，且平台团队能够长期维护壳与协议时，重新评估微前端。若模块化规则本身造成显著交付延迟，也应先检查边界是否划分错误。</p>',37)])])}const p=a(i,[["render",o]]);export{_ as __pageData,p as default};
